input.command:
cd . && python3 - <<'E'
p='hbexpense/services/reports.py'
s=open(p).read()
s+='''
    def ledger_statuses(self, claims):
        """Map claim id -> "booked" / "not_booked" / None, read live from the ledger.

        Uses period listings only (one per month), never per-receipt lookups.
        """
        months = {}
        for claim in claims:
            if claim.receipt:
                months.setdefault(month_of(claim.spent_on), None)
        for month in months:
            date_from, date_to = month_bounds(month)
            months[month] = {r.receipt for r in self.ledger.list_rows(date_from, date_to)}
        result = {}
        for claim in claims:
            if not claim.receipt:
                result[claim.claim_id] = None
            elif claim.receipt in months[month_of(claim.spent_on)]:
                result[claim.claim_id] = "booked"
            else:
                result[claim.claim_id] = "not_booked"
        return result
'''
s=s.replace("import month_bounds","import month_bounds, month_of")
open(p,'w').write(s)
p='hbexpense/api/handlers.py'
s=open(p).read()
s=s.replace('''def get_claim(app, request, claim_id):
    return Response.ok(app.repo.get(claim_id).to_dict())
''','''def _with_ledger_status(app, claims):
    statuses = app.services["reports"].ledger_statuses(claims)
    return [dict(c.to_dict(), ledger_status=statuses[c.claim_id]) for c in claims]


def get_claim(app, request, claim_id):
    return Response.ok(_with_ledger_status(app, [app.repo.get(claim_id)])[0])
''')
s=s.replace('{"items": [c.to_dict() for c in claims]}','{"items": _with_ledger_status(app, claims)}')
open(p,'w').write(s)
E
grep -n "def month_of" -A5 hbexpense/util/dates.py; bash test.sh 2>&1 | tail -8

